            for row in data:
                print(f"{row['dosya']:<25} | {row['error']:<5} | {row['warn']:<5} | {row['info']:<5}")

            # Sıralama kontrolü: error azalan, dosya artan
            for i in range(len(data) - 1):
                current = data[i]
                next_row = data[i+1]

                # Error azalan mı?
                if int(current['error']) < int(next_row['error']):
                    return f"Hata: Sıralama yanlış (Error azalan olmalı). {current['error']} < {next_row['error']}"

                # Errorler eşitse dosya adı artan mı?
                if int(current['error']) == int(next_row['error']):
                    if current['dosya'] > next_row['dosya']:
                        return f"Hata: Eşit error durumunda sıralama yanlış. {current['dosya']} > {next_row['dosya']}"

            return "Doğrulama Başarılı: Sıralama ve içerik kurallara uygun görünüyor."
    except Exception as e:
        return f"Doğrulama Hatası: {e}"

print(verify_csv())

